<?php
require_once __DIR__ . '/_layout.php'; requirePermission('reservations.manage');
function renderMessageTemplate($template,array $values){foreach($values as $key=>$value)$template=str_replace('{{'.$key.'}}',(string)$value,$template);return$template;}
if(requestMethod()==='POST'){requireCsrfPost();try{$reservation=dbFetchOne('SELECT r.*,c.first_name,c.last_name,c.email,c.phone,v.registration_number FROM reservations r JOIN customers c ON c.id=r.customer_id LEFT JOIN vehicles v ON v.id=r.vehicle_id WHERE r.id=:id',['id'=>(int)($_POST['reservation_id']??0)]);if(!$reservation)throw new InvalidArgumentException('Reservation not found.');requireAgencyAccess($reservation['agency_id']);$type=validateChoice($_POST['notification_type']??'',['reservation_confirmation','pickup_reminder','return_reminder','late_return','payment_reminder','deposit_return_reminder','vehicle_ready'],'reservation_confirmation');$lang=validateChoice($_POST['language_code']??'',supportedLanguages(),'fr');$template=dbFetchOne("SELECT * FROM notification_templates WHERE notification_type=:type AND language_code=:lang AND (agency_id=:agency OR agency_id IS NULL) AND status='active' ORDER BY agency_id DESC LIMIT 1",['type'=>$type,'lang'=>$lang,'agency'=>$reservation['agency_id']]);$values=['reference'=>$reservation['reference'],'pickup_at'=>$reservation['pickup_at'],'return_at'=>$reservation['return_at'],'vehicle'=>$reservation['registration_number'],'customer'=>$reservation['first_name'].' '.$reservation['last_name']];$message=renderMessageTemplate($template['message_template']??'Reservation {{reference}}: {{pickup_at}} — {{return_at}}',$values);$subject=renderMessageTemplate($template['subject_template']??'Reservation {{reference}}',$values);$channel=validateChoice($_POST['channel']??'',['internal','email','whatsapp'],'internal');$recipient=$channel==='email'?$reservation['email']:$reservation['phone'];$status='ready';if($channel==='email'&&$recipient){$status=@mail($recipient,$subject,$message,"Content-Type: text/plain; charset=UTF-8\r\n")?'sent':'failed';}dbExecute('INSERT INTO notifications(agency_id,reservation_id,notification_type,channel,recipient,language_code,subject,message,status,sent_at,created_by)VALUES(:agency,:reservation,:type,:channel,:recipient,:lang,:subject,:message,:status,:sent_at,:user)',['agency'=>$reservation['agency_id'],'reservation'=>$reservation['id'],'type'=>$type,'channel'=>$channel,'recipient'=>$recipient,'lang'=>$lang,'subject'=>$subject,'message'=>$message,'status'=>$status,'sent_at'=>$status==='sent'?date('Y-m-d H:i:s'):null,'user'=>currentUserId()]);auditLog('notification.created','notification',db()->lastInsertId(),null,['type'=>$type,'channel'=>$channel,'status'=>$status],$reservation['agency_id']);flash($status==='failed'?'danger':'success',$status==='failed'?'Email delivery failed; the message remains in history.':'Notification prepared.');}catch(InvalidArgumentException|DomainException $exception){flash('danger',$exception->getMessage());}catch(Throwable $exception){reportDatabaseError($exception,'Notification operation failed');flash('danger','The notification could not be prepared.');}safeRedirect('notifications.php');}
$ids=currentAgencyIds();if(!$ids)$ids=[0];$ph=implode(',',array_fill(0,count($ids),'?'));$reservations=dbFetchAll("SELECT r.id,r.reference,c.first_name,c.last_name FROM reservations r JOIN customers c ON c.id=r.customer_id WHERE r.agency_id IN ($ph) AND r.status NOT IN ('cancelled','expired') ORDER BY r.created_at DESC LIMIT 200",$ids);$notifications=dbFetchAll("SELECT n.*,r.reference FROM notifications n LEFT JOIN reservations r ON r.id=n.reservation_id WHERE n.agency_id IN ($ph) ORDER BY n.created_at DESC LIMIT 100",$ids);
backofficeHeader('Notifications','notifications.php');?><?php pageHeader('Notifications', 'Prepare customer messages and review delivery history.', ['breadcrumbs'=>[['label'=>'Overview'],['label'=>'Notifications']],'primary'=>['label'=>'Prepare notification','href'=>'#new-notification']]); ?><div class="grid"><section class="card" id="new-notification"><h2>Prepare notification</h2><form method="post"><?=csrfField()?><label>Reservation<select name="reservation_id"><?php foreach($reservations as $r):?><option value="<?=e($r['id'])?>"><?=e($r['reference'].' — '.$r['first_name'].' '.$r['last_name'])?></option><?php endforeach;?></select></label><label>Type<select name="notification_type"><?php foreach(['reservation_confirmation','pickup_reminder','return_reminder','late_return','payment_reminder','deposit_return_reminder','vehicle_ready'] as $type):?><option><?=e($type)?></option><?php endforeach;?></select></label><label>Language<select name="language_code"><option value="fr">Français</option><option value="ar">العربية</option><option value="en">English</option></select></label><label>Channel<select name="channel"><option>internal</option><option>email</option><option>whatsapp</option></select></label><button class="btn primary">Prepare / send</button></form></section><section class="card"><h2>History</h2><div class="table-wrap"><table><tr><th>Created</th><th>Reservation</th><th>Channel</th><th>Recipient</th><th>Message</th><th>Status</th></tr><?php foreach($notifications as $n):?><tr><td><?=e($n['created_at'])?></td><td><?=e($n['reference'])?></td><td><?=e($n['channel'])?></td><td><?=e($n['recipient'])?></td><td style="white-space:normal;min-width:280px"><?=e($n['message'])?><?php if($n['channel']==='whatsapp'&&normalizedPhone($n['recipient'])):?><br><a target="_blank" rel="noopener" href="https://wa.me/<?=e(normalizedPhone($n['recipient']))?>?text=<?=e(rawurlencode($n['message']))?>">Open WhatsApp</a><?php endif;?></td><td><?=statusBadge($n['status'])?></td></tr><?php endforeach;?></table></div></section></div><?php backofficeFooter();
